#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    // Max heap for left half (store negatives for max heap)
    multiset<int> left;
    // Min heap for right half
    multiset<int> right;

    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;

        // Insert
        if (left.empty() || x <= *left.rbegin()) {
            left.insert(x);
        } else {
            right.insert(x);
        }

        // Balance
        if (left.size() > right.size() + 1) {
            right.insert(*left.rbegin());
            left.erase(prev(left.end()));
        } else if (right.size() > left.size()) {
            left.insert(*right.begin());
            right.erase(right.begin());
        }

        // Get median
        if (left.size() == right.size()) {
            cout << (*left.rbegin() + *right.begin()) / 2.0 << " ";
        } else {
            cout << *left.rbegin() << " ";
        }
    }
    cout << "\n";

    return 0;
}

